let sequence=91;
export const handbookGroups=groups.map(group=>{
 const questions=group.rows.trim().split('\n').map(line=>{
  const cells=line.split('|');
  if(cells.length!==8)throw new Error(`Invalid handbook row: ${line}`);
  const [question,questionDari,rule,ruleDari,b,bd,c,cd]=cells;
  const id=`ca-${String(sequence++).padStart(3,'0')}`;
  const q:ExtraQuestion={id,topic:group.topic,chapter:group.chapter,question,questionDari,options:[rule,b,c],optionsDari:[ruleDari,bd,cd],answer:0,explanation:rule,explanationDari:ruleDari,source:`https://www.dmv.ca.gov/portal/handbook/california-driver-handbook/${group.slug}/`};
  return q;
 });
 if(questions.length%3)throw new Error(`Handbook group needs complete three-question levels: ${group.chapter}`);
 return {...group,questions};
});
export const handbookExpansion=handbookGroups.flatMap(g=>g.questions);
